%[text] # View input signals
evalin("base", "loadLUTData_Vehicle1D_Braking")

fig = figure; %[output:92d55ec5]
fig.Position(3:4) = [900 200];  % width height %[output:92d55ec5]

x_unit_text = string(unit(BrakeForceInput.Time));
f_unit_text = string(unit(BrakeForceInput.Force));

bevutil1.SignalUtil.plotLookupTable1D( ... %[output:group:0ef6311d] %[output:92d55ec5]
  BrakeForceInput.Time.value(x_unit_text), ... %[output:92d55ec5]
  BrakeForceInput.Force.value(f_unit_text), ... %[output:92d55ec5]
  InterpolationInterval = 0.2, ... %[output:92d55ec5]
  Title = "Brake force input", ... %[output:92d55ec5]
  XLabel = "Time (" + x_unit_text + ")", ... %[output:92d55ec5]
  YLabel = f_unit_text, ... %[output:92d55ec5]
  ParentAxes = axes(fig) ) %[output:group:0ef6311d] %[output:92d55ec5]
fig = figure; %[output:48b5036b]
fig.Position(3:4) = [900 200];  % width height %[output:48b5036b]

x_unit_text = string(unit(RoadGradeInput.Time));
f_unit_text = "\%";

bevutil1.SignalUtil.plotLookupTable1D( ... %[output:group:6fe490c4] %[output:48b5036b]
  RoadGradeInput.Time.value(x_unit_text), ... %[output:48b5036b]
  RoadGradeInput.Grade, ... %[output:48b5036b]
  InterpolationInterval = 0.2, ... %[output:48b5036b]
  Title = "Road grade input", ... %[output:48b5036b]
  XLabel = "Time (" + x_unit_text + ")", ... %[output:48b5036b]
  YLabel = f_unit_text, ... %[output:48b5036b]
  ParentAxes = axes(fig) ) %[output:group:6fe490c4] %[output:48b5036b]
